create or replace function get_schedule_week_index_v1(p_date date) returns integer language sql stable security definer set search_path=public as $$select case when y.teaching_starts_on is null then null else 1+floor((p_date-coalesce(p.week_parity_anchor,date_trunc('week',y.teaching_starts_on)::date))/7.0)::int end from schedule_time_profiles p join academic_years y on y.institution_code=p.institution_code and y.active where p.active and p.institution_code=current_tenant_code() order by p.updated_at desc limit 1$$;
create or replace function schedule_week_pattern_applies_v1(p_pattern text,p_date date) returns boolean language sql stable security definer set search_path=public as $$select case upper(coalesce(p_pattern,'ALL')) when 'ALL' then true when 'ODD' then coalesce(get_schedule_week_index_v1(p_date)%2=1,false) when 'EVEN' then coalesce(get_schedule_week_index_v1(p_date)%2=0,false) else false end$$;
create or replace function is_teaching_day(p_date date) returns boolean language plpgsql stable security definer set search_path=public as $$declare y academic_years%rowtype;p schedule_time_profiles%rowtype;begin select * into y from academic_years where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;if not found or y.teaching_starts_on is null or y.teaching_ends_on is null or p_date not between y.teaching_starts_on and y.teaching_ends_on then return false;end if;select * into p from schedule_time_profiles where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;if not found or not(extract(isodow from p_date)::smallint=any(p.teaching_days)) then return false;end if;if exists(select 1 from school_calendar_events e where e.academic_year_id=y.id and tenant_row_allowed(e.institution_code) and e.blocks_teaching and p_date between e.starts_on and e.ends_on) then return false;end if;return true;end$$;
create or replace function schedule_assignment_applies_on_date_v1(p_assignment uuid,p_date date) returns boolean language plpgsql stable security definer set search_path=public as $$declare a teacher_course_assignments%rowtype;y academic_years%rowtype;begin select * into a from teacher_course_assignments where id=p_assignment and tenant_row_allowed(institution_code);if not found or not is_teaching_day(p_date) then return false;end if;select * into y from academic_years where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;if a.valid_from is not null and p_date<a.valid_from then return false;end if;if a.valid_to is not null and p_date>a.valid_to then return false;end if;if a.term_no=1 and (y.teaching_starts_on is null or y.first_term_ends_on is null or p_date not between y.teaching_starts_on and y.first_term_ends_on) then return false;end if;if a.term_no=2 and (y.second_term_starts_on is null or y.teaching_ends_on is null or p_date not between y.second_term_starts_on and y.teaching_ends_on) then return false;end if;return schedule_week_pattern_applies_v1(a.week_pattern,p_date);end$$;
create or replace function schedule_assignment_scopes_overlap_v1(p_a uuid,p_b uuid) returns boolean language plpgsql stable security definer set search_path=public as $$declare a teacher_course_assignments%rowtype;b teacher_course_assignments%rowtype;y academic_years%rowtype;af date;at date;bf date;bt date;begin if p_a is null or p_b is null then return true;end if;select * into a from teacher_course_assignments where id=p_a and tenant_row_allowed(institution_code);select * into b from teacher_course_assignments where id=p_b and tenant_row_allowed(institution_code);if a.id is null or b.id is null then return true;end if;select * into y from academic_years where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;if y.id is null then return true;end if;af:=coalesce(a.valid_from,y.teaching_starts_on,y.starts_on);at:=coalesce(a.valid_to,y.teaching_ends_on,y.ends_on);bf:=coalesce(b.valid_from,y.teaching_starts_on,y.starts_on);bt:=coalesce(b.valid_to,y.teaching_ends_on,y.ends_on);if af is not null and bt is not null and af>bt then return false;end if;if bf is not null and at is not null and bf>at then return false;end if;if a.term_no is not null and b.term_no is not null and a.term_no<>b.term_no then return false;end if;if(a.week_pattern='ODD' and b.week_pattern='EVEN')or(a.week_pattern='EVEN' and b.week_pattern='ODD')then return false;end if;return true;end$$;
create or replace function schedule_slots_overlap_state_v1(p_session_a uuid,p_period_a smallint,p_session_b uuid,p_period_b smallint) returns text language plpgsql stable security definer set search_path=public as $$declare a schedule_period_definitions%rowtype;b schedule_period_definitions%rowtype;begin if p_session_a is null or p_session_b is null then return case when p_period_a=p_period_b then 'OVERLAP' else 'UNKNOWN' end;end if;select * into a from schedule_period_definitions where session_id=p_session_a and period=p_period_a and active and tenant_row_allowed(institution_code);select * into b from schedule_period_definitions where session_id=p_session_b and period=p_period_b and active and tenant_row_allowed(institution_code);if a.id is null or b.id is null or a.starts_at is null or a.ends_at is null or b.starts_at is null or b.ends_at is null then if p_session_a=p_session_b then return case when p_period_a=p_period_b then 'OVERLAP' else 'NO_OVERLAP' end;else return 'UNKNOWN';end if;end if;return case when a.starts_at<b.ends_at and b.starts_at<a.ends_at then 'OVERLAP' else 'NO_OVERLAP' end;end$$;
create or replace function schedule_slots_overlap_v1(p_session_a uuid,p_period_a smallint,p_session_b uuid,p_period_b smallint) returns boolean language sql stable security definer set search_path=public as $$select schedule_slots_overlap_state_v1(p_session_a,p_period_a,p_session_b,p_period_b)<>'NO_OVERLAP'$$;
create or replace function schedule_requirement_slot_allowed_v1(p_requirement uuid,p_period smallint) returns boolean language plpgsql stable security definer set search_path=public as $$declare sid uuid;n int;mx int;begin select c.schedule_session_id into sid from class_course_requirements r join school_classes c on c.id=r.class_id where r.id=p_requirement and tenant_row_allowed(r.institution_code);if sid is null then return false;end if;select count(*) into n from schedule_period_definitions where session_id=sid and active and tenant_row_allowed(institution_code);if n>0 then return exists(select 1 from schedule_period_definitions where session_id=sid and period=p_period and active and tenant_row_allowed(institution_code));end if;select count(*) into n from schedule_sessions where active and tenant_row_allowed(institution_code);select periods_per_day into mx from schedule_time_profiles where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;return n=1 and p_period between 1 and coalesce(mx,0);end$$;
create or replace function schedule_slot_open_on_date_v1(p_date date,p_session uuid,p_period smallint) returns boolean language plpgsql stable security definer set search_path=public as $$declare s text;begin if not is_teaching_day(p_date) then return false;end if;select state into s from schedule_calendar_slot_overrides where calendar_date=p_date and session_id=p_session and period=p_period and tenant_row_allowed(institution_code);if s='CLOSED' then return false;end if;return true;end$$;
create or replace function get_schedule_assignment_time_model_v1() returns table(assignment_id uuid,week_pattern text,valid_from date,valid_to date,term_no smallint,schedule_session_id uuid,allowed_periods smallint[]) language sql stable security definer set search_path=public as $$with p as(select * from schedule_time_profiles where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1),sc as(select count(*) n from schedule_sessions where active and tenant_row_allowed(institution_code)) select a.id,a.week_pattern,a.valid_from,a.valid_to,a.term_no,coalesce(a.schedule_session_id,c.schedule_session_id),case when exists(select 1 from schedule_period_definitions d where d.session_id=coalesce(a.schedule_session_id,c.schedule_session_id) and d.active and tenant_row_allowed(d.institution_code)) then array(select d.period from schedule_period_definitions d where d.session_id=coalesce(a.schedule_session_id,c.schedule_session_id) and d.active and tenant_row_allowed(d.institution_code) order by d.period)::smallint[] when(select n from sc)=1 then array(select generate_series(1,(select periods_per_day from p))::smallint) else '{}'::smallint[] end from teacher_course_assignments a join class_course_requirements r on r.id=a.class_course_requirement_id join school_classes c on c.id=r.class_id where tenant_row_allowed(a.institution_code)$$;
create or replace function get_schedule_time_model_health_v1() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('sessions',(select count(*) from schedule_sessions where active and tenant_row_allowed(institution_code)),'period_definitions',(select count(*) from schedule_period_definitions where active and tenant_row_allowed(institution_code)),'classes_without_session',(select count(*) from school_classes where active and tenant_row_allowed(institution_code) and schedule_session_id is null),'assignments_without_session',(select count(*) from teacher_course_assignments where tenant_row_allowed(institution_code) and schedule_session_id is null),'scoped_assignments',(select count(*) from teacher_course_assignments where tenant_row_allowed(institution_code) and(week_pattern<>'ALL' or term_no is not null or valid_from is not null or valid_to is not null)),'multi_session_clock_missing',(select count(*) from schedule_sessions s where s.active and tenant_row_allowed(s.institution_code) and(not exists(select 1 from schedule_period_definitions d where d.session_id=s.id and d.active)or exists(select 1 from schedule_period_definitions d where d.session_id=s.id and d.active and(d.starts_at is null or d.ends_at is null)))and(select count(*) from schedule_sessions x where x.active and tenant_row_allowed(x.institution_code))>1))$$;
create or replace function get_teacher_schedule_for_date_v1(p_teacher uuid,p_date date default current_date) returns table(source_schedule_id uuid,teacher_assignment_id uuid,period smallint,class_id uuid,class_name text,subject text,course_id uuid,classroom_id uuid,subgroup_id uuid,schedule_session_id uuid) language sql stable security definer set search_path=public as $$select ts.id,ts.teacher_assignment_id,ts.period,ts.class_id,ts.class_name,ts.subject,ts.course_id,ts.classroom_id,ts.subgroup_id,ts.schedule_session_id from teacher_schedule ts where ts.active and ts.teacher_id=p_teacher and ts.weekday=extract(isodow from p_date)::smallint and tenant_row_allowed(ts.institution_code) and schedule_assignment_applies_on_date_v1(ts.teacher_assignment_id,p_date) and schedule_slot_open_on_date_v1(p_date,ts.schedule_session_id,ts.period) order by ts.period$$;
do $$declare d text;begin select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='validate_schedule_semantics_v2';d:=replace(d,'new.subject:=v_course.name;','new.subject:=v_course.name; new.schedule_session_id:=coalesce(v_assignment.schedule_session_id,(select schedule_session_id from public.school_classes where id=v_req.class_id)); if new.schedule_session_id is null then raise exception ''SCHEDULE_SESSION_REQUIRED'';end if; if not public.schedule_requirement_slot_allowed_v1(v_req.id,new.period) then raise exception ''PERIOD_OUTSIDE_SESSION'';end if; if exists(select 1 from public.teacher_schedule ts where ts.active and ts.teacher_id=new.teacher_id and ts.weekday=new.weekday and ts.period=new.period and ts.id<>coalesce(new.id,v_zero) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)) then raise exception ''TEACHER_DOUBLE_BOOKING'';end if;');d:=replace(d,'ts.weekday=new.weekday and ts.period=new.period and ts.id<>coalesce(new.id,v_zero)','ts.weekday=new.weekday and ts.period=new.period and ts.id<>coalesce(new.id,v_zero) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)');d:=replace(d,'u.weekday=new.weekday and u.period=new.period and u.active','u.weekday=new.weekday and u.period=new.period and u.active and (u.schedule_session_id is null or u.schedule_session_id=new.schedule_session_id)');d:=replace(d,'ts.teacher_id=new.teacher_id and ts.weekday=new.weekday and ts.active and ts.id<>coalesce(new.id,v_zero)','ts.teacher_id=new.teacher_id and ts.weekday=new.weekday and ts.active and ts.id<>coalesce(new.id,v_zero) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)');d:=replace(d,'ts.teacher_id=new.teacher_id and ts.active and ts.id<>coalesce(new.id,v_zero)','ts.teacher_id=new.teacher_id and ts.active and ts.id<>coalesce(new.id,v_zero) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)');execute d;select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='validate_schedule_room_pool_v1';d:=replace(d,'ts.id<>coalesce(new.id,''00000000-0000-0000-0000-000000000000''::uuid)','ts.id<>coalesce(new.id,''00000000-0000-0000-0000-000000000000''::uuid) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)');execute d;select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='validate_schedule_building_transfer_v1';d:=replace(d,'ts.classroom_id is not null and ts.period in(new.period-1,new.period+1)','ts.classroom_id is not null and ts.period in(new.period-1,new.period+1) and public.schedule_assignment_scopes_overlap_v1(ts.teacher_assignment_id,new.teacher_assignment_id)');execute d;select pg_get_functiondef(p.oid) into d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='get_schedule_daily_effective_v2';d:=replace(d,'ts.weekday=extract(isodow from p_date)::smallint and not exists','ts.weekday=extract(isodow from p_date)::smallint and public.schedule_assignment_applies_on_date_v1(ts.teacher_assignment_id,p_date) and public.schedule_slot_open_on_date_v1(p_date,ts.schedule_session_id,ts.period) and not exists');execute d;end$$;
drop trigger if exists trg_validate_schedule_slot on teacher_schedule;alter table schedule_scenario_rows drop constraint if exists schedule_scenario_rows_scenario_id_teacher_id_weekday_perio_key,drop constraint if exists schedule_scenario_rows_scenario_id_class_id_weekday_period__key;create index if not exists idx_scenario_teacher_slot on schedule_scenario_rows(scenario_id,teacher_id,weekday,period);create index if not exists idx_scenario_class_slot on schedule_scenario_rows(scenario_id,class_id,weekday,period);
create or replace function validate_schedule_scenario_temporal_v1() returns trigger language plpgsql security definer set search_path=public as $$declare a teacher_course_assignments%rowtype;z uuid:='00000000-0000-0000-0000-000000000000';begin if new.teacher_assignment_id is not null then select * into a from teacher_course_assignments where id=new.teacher_assignment_id;if found then new.schedule_session_id:=coalesce(a.schedule_session_id,(select schedule_session_id from school_classes where id=new.class_id));if not schedule_requirement_slot_allowed_v1(a.class_course_requirement_id,new.period) then raise exception 'PERIOD_OUTSIDE_SESSION';end if;end if;end if;if exists(select 1 from schedule_scenario_rows x where x.scenario_id=new.scenario_id and x.id<>coalesce(new.id,z) and x.teacher_id=new.teacher_id and x.weekday=new.weekday and x.period=new.period and schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,new.teacher_assignment_id)) then raise exception 'SCENARIO_TEACHER_DOUBLE_BOOKING';end if;if new.class_id is not null and exists(select 1 from schedule_scenario_rows x where x.scenario_id=new.scenario_id and x.id<>coalesce(new.id,z) and x.class_id=new.class_id and x.weekday=new.weekday and x.period=new.period and schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,new.teacher_assignment_id) and(new.subgroup_id is null or x.subgroup_id is null or x.subgroup_id=new.subgroup_id or exists(select 1 from class_subgroup_students q join class_subgroup_students w on w.student_id=q.student_id where q.subgroup_id=new.subgroup_id and w.subgroup_id=x.subgroup_id))) then raise exception 'SCENARIO_CLASS_OR_GROUP_CONFLICT';end if;if new.classroom_id is not null and exists(select 1 from schedule_scenario_rows x where x.scenario_id=new.scenario_id and x.id<>coalesce(new.id,z) and x.classroom_id=new.classroom_id and x.weekday=new.weekday and x.period=new.period and schedule_assignment_scopes_overlap_v1(x.teacher_assignment_id,new.teacher_assignment_id)) then raise exception 'SCENARIO_ROOM_DOUBLE_BOOKING';end if;return new;end;$$;drop trigger if exists trg_validate_schedule_scenario_temporal_v1 on schedule_scenario_rows;create trigger trg_validate_schedule_scenario_temporal_v1 before insert or update on schedule_scenario_rows for each row execute function validate_schedule_scenario_temporal_v1();
